import sys,json,hashlib,struct
root=Path(__file__).resolve().parent;sys.argv=['qualify_designing_closures.py','bitcrush'];ns={'__file__':str(root/'qualify_designing_closures.py')};exec((root/'qualify_designing_closures.py').read_text().split('rows=[]')[0],ns);run=ns['run'];sha=lambda b:hashlib.sha256(b).hexdigest();out=root/'bitdsp-check';out.mkdir(exist_ok=True);rows=[]
