 (d/'driver.cpp').write_text(ns['base']+'\n#include "generated.hpp"\n'+body);run(['g++','-O1','-ffp-contract=off','-fno-fast-math',str(d/'driver.cpp'),'-o',str(d/'render')]);run([str(d/'render'),str(d/'capture.bin')]);rows.append(dict(candidate=name,source_sha256=sha(source.read_bytes()),capture_sha256=sha((d/'capture.bin').read_bytes()),cases=8 if name=='full_adder' else 256,frames=8 if name=='full_adder' else 1024,status='BINARY_DOMAIN_ORACLE_PASS'))
